    pendingPinContext = buildElementContext(el, CTX_MAX_BYTES);
    var extras = {
      anchor: pendingPinAnchor,
      pinpoint: !!viaPinpoint,
      targetKey: pendingPinKey,
      targetLabel: pendingPinLabel,
      context: pendingPinContext
    };
